insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 2, 6, $json${"week":2,"day":6,"title":"The other way in","heading":"The lip of the shaft","question":"is there another way in, and how long is left?","steps":[{"t":"say","text":"Your second night on the hill. Two lamps burn at the foot of the shaft, and the ladder has not come back.\n\nIt is your watch. You lie on your belly at the lip, with the cold coming up out of the ground into your elbows."},{"t":"notice","lines":{"Might":{"first":"Under your palm the ground is trembling, very slightly.","second":"It is not the river."},"Agility":{"first":"The two at the foot of the shaft change places every little while.","second":"They are tired. They have been at this for days."},"Intellect":{"first":"They have not come up after you, and they have not put their lamps out.","second":"They are not afraid of you. They are only keeping you where you are."},"Charm":{"first":"The chanting has started again.","second":"Whatever they were making ready is nearly ready."},"Craft":{"first":"A sound comes up the shaft, and then the same sound comes up through the ground, a moment later.","second":"There is more hollow under this hill than one room."},"Aim":{"first":"The lamplight at the bottom dims and brightens.","second":"People are crossing in front of it, and all of them the same way."}}},{"t":"challenge","title":"READ THE HILL","desc":"You cannot see them. You can hear them, and you can watch their light.","options":[{"attr":"Aim","verb":"count the shapes crossing the lamp, and place them"},{"attr":"Might","verb":"haul yourself up to the crack above the lamp, and look down into it"}],"reward":"+500g","fail":"you know only that there are many, and that they are busy"},{"t":"say","text":"Shape by shape, you place them as they cross the light. You have them: a knot of them at the lamps, a steady file beyond, all going the same way. And one who does not move at all, and is small.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You watch until your eyes ache from the lamplight and the shapes run together. There are many. They are busy. That is all the hill will tell you.","cond":{"on":"challenge","pass":false}},{"t":"press","title":"EAR TO THE ROCK","detail":"listen below the room you can place","harder":4,"reward":"+200g, and one more detail"},{"t":"say","text":"You lay your ear to the cold rock and wait for the chant to come round again. Above, it is muffled and close. Below it there is something else: a silence with room in it.\n\nUnder the room with the lamps there is another hollow. It is bigger. And there is nobody in it at all.","cond":{"on":"press"}},{"t":"say","text":"Somewhere in the long hours it turns up: not hidden, this time. Lying among the roots at the lip of the shaft, as if it had been dropped there yesterday."},{"t":"act","label":"PICK IT UP"},{"t":"say","text":"**A locked Seeker Fragment has been added to your Chest.**\n\nThat is six.","fragment":true},{"t":"act","label":"LAY THEM OUT"},{"t":"say","text":"They move, as the first six did. Each turns a little, and settles against the next. And then they are one thing.\n\nA map, old and exact. It points into this same hill. Not to the chamber that drove you back, but deeper: to an older room, reached by a shaft of its own, cut long before any of those hooded figures was born."},{"t":"say","text":"{F3} has crawled up beside you at the lip to look. Whoever else is on watch along the hillside is too far off to pass a map to, and they have to have it too."},{"t":"choice","id":0,"labels":["READ IT OUT","LET {F3} READ IT"],"mode":"flavor","branches":[]},{"t":"say","text":"It is said aloud, twice, across the dark, so that everybody has it.\n\nThe night is very still. Sound carries."},{"t":"say","text":"The map marks a place two hundred paces along the hill."},{"t":"act","label":"GO AND PUT YOUR HAND TO IT"},{"t":"say","text":"A fall of old stone, grown over. Under it, when you have shifted enough of it: a hole. Cold air is breathing out of it.\n\nIt is real. And nobody is guarding it."},{"t":"say","text":"Within the hour, the hill wakes.\n\nLamps. Feet. A child's voice, cut short. All of it moving deeper.\n\nAnd then, far down in the rock: picks."},{"t":"say","text":"Even here, Garrick pours one more cup than there are of you, and sets it on a flat stone at the empty place. There is not much left in the flask. He pours it anyway."},{"t":"say","text":"**They are digging toward the old room. Be in it first.**","pull":true},{"t":"summary","lines":["**THE OTHER WAY IN** · Day 6","You earned: `[gold]` · Aim or Might `[growth]`","You learned: **the six fragments are a map again.** It shows an older room, deeper in the same hill, with a shaft of its own. You found its mouth. Nobody is guarding it. They are digging toward that room now.","*On a failure:* You missed something on the hill. Someone at the fire may have seen it.","You hold: the map · the black circle","Fragments: 6 of 6 · the map is whole","Tomorrow: **THE GATHERING** · into the hill by the old shaft, together"]}]}$json$::jsonb, $json${"dc":7,"wDef":23,"wAtk":16,"fightReward":0}$json$::jsonb)
insert into public.chapters (series_id, season_number, week, day, script, meta) values
('dark-moon', 1, 3, 6, $json${"week":3,"day":6,"title":"The cairn","heading":"The cairn","question":"where have they taken her?","steps":[{"t":"say","text":"All afternoon the cairn has been in sight: a dark knuckle of piled stones far off on the skyline, that never seems to come any nearer. Every ridge you cross shows you another between you and it. The shadows are long now, and reaching.\n\nThe cairn stands on the highest ridge in the burned country, and the light is going."},{"t":"notice","lines":{"Might":{"first":"The lowest stones of that cairn are as big as sheep.","second":"Nobody carried those up there for a landmark."},"Agility":{"first":"The wind is rising as the light goes.","second":"In an hour that ridge will be no place to stand."},"Intellect":{"first":"The Blackglass, the buried room and the hut lie in a line.","second":"A line points somewhere."},"Charm":{"first":"Nobody has said her name all day.","second":"There are eight of her chips among you."},"Craft":{"first":"One hill out there is too round.","second":"The others were worn down. That one was melted."},"Aim":{"first":"Over one hill, and only one, the air is moving like the air over a forge.","second":"Something under that hill is still hot."}}},{"t":"challenge","title":"THE CLIMB","desc":"There is an hour of light, and more than an hour of ridge.","options":[{"attr":"Might","verb":"straight up the face"},{"attr":"Agility","verb":"along the knife-edge, where it is shorter and worse"}],"reward":"+500g","fail":"you get there in the dark, and see nothing but what you carry"},{"t":"say","text":"You come up beside the cairn with the sun still on the ridges, and the whole burned country is spread out under you: the Blackglass shining dully to the west, the green fold of the hut far below.\n\nAnd one hill unlike all the others. Round, and black, with a crack across its crown, where the air above it shimmers as if the hill were breathing.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"The last of the ridge you climb by feel, with the wind pulling at your coat and the rock still warm under your hands.\n\nIt is full dark when you reach the cairn. There is nothing to see from it but black on black, and the stars.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"The last fragment is at the cairn's foot: not hidden, only wedged between the lowest stones, where a careless boot would miss it."},{"t":"act","label":"TAKE IT"},{"t":"say","text":"**A locked Seeker Fragment has been added to your Chest.**\n\nThat is six.","fragment":true},{"t":"act","label":"LAY THEM OUT"},{"t":"say","text":"They settle, as they have twice before. The wind worries at their edges, and they do not lift. A map, old and exact, with a ridgeline drawn along its top."},{"t":"act","label":"TURN IT TO THE SKYLINE"},{"t":"say","text":"You turn it until the drawn ridges sit on the real ones. They fit. And the place the map ends is the round hill with the crack in its crown. You were looking at it before the map told you.","cond":{"on":"challenge","pass":true}},{"t":"say","text":"You turn it until the drawn ridges sit on the black shapes against the stars. They fit. The place the map ends is a round hill you can only just make out, with a notch in its crown.","cond":{"on":"challenge","pass":false}},{"t":"say","text":"*\"The Kiln,\"* Garrick says. *\"That's the shepherds' name for it.\"*"},{"t":"say","text":"In through the crack. Down a way cut long ago. To a room beneath the hill."},{"t":"say","text":"{F1} came up the last of the ridge at your side. Whoever is still on the slope below is too far down to see what you hold."},{"t":"choice","id":0,"labels":["READ IT OUT","LET {F1} READ IT"],"mode":"flavor","branches":[]},{"t":"say","text":"It is said aloud, twice, for the ones on the slope below. The wind takes every word of it down the ridge."},{"t":"say","text":"The cold comes up fast once the sun is gone. Garrick builds the fire up, and gives whoever is shivering hardest the warm side of it."},{"t":"say","text":"Not an hour after full dark, far below: a single lamp, moving across the black ground toward the Kiln.\n\nIt reaches the foot of the hill. It climbs. And it goes out.\n\nNot blown out. Gone in."},{"t":"say","text":"**Whatever happens under that hill has started. Into the Kiln, tonight.**","pull":true},{"t":"summary","lines":["**THE CAIRN** · Day 6","You earned: `[gold]` · Might or Agility `[growth]`","You learned: **the Kiln.** A round black hill that breathes warm air through a crack in its crown. The map goes in through that crack, to a room beneath. A lamp has just gone in ahead of you.","*On a failure:* You missed something at the cairn. Someone at the fire may have seen it.","You hold: the map · eight of Wren's chips","Fragments: 6 of 6 · the map is whole","Tomorrow: **THE GATHERING** · down through the Kiln's crown, together"]}]}$json$::jsonb, $json${"dc":7,"wDef":24,"wAtk":17,"fightReward":0}$json$::jsonb)
